<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/index')}" class="on">【<if condition="$now_user.nickname neq ''">{pigcms{$now_user.nickname}<else />用户ID{pigcms{$now_user.uid}</if>】第{pigcms{$_GET['lvl']}级上级用户</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th>ID</th>								<th>昵称</th>								<th>手机号</th>								<th>最后登录时间</th>								<th>最后登录地址</th>								<th class="textcenter">余额</th>								<th class="textcenter">{pigcms{$config['score_name']}</th>								<th class="textcenter">来源</th>								<th class="textcenter">状态</th>								<if condition="$config.open_user_spread eq 1"><th class="textcenter">推广用户</th></if>								<if condition="$config.open_user_spread eq 1"><th class="textcenter">获得的推广佣金</th></if>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="count($user_list) gt 0">								<volist name="user_list" id="vo">									<tr>										<td>{pigcms{$vo.uid}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}</td>										<td>{pigcms{$vo.last_ip_txt}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.now_money|floatval=###}</td>										<td class="textcenter">{pigcms{$vo.score_count}</td>										<td class="textcenter"><php>if(strpos($vo['source'],'weixin')===0){</php>										{pigcms{$client.5}										<php>}elseif(strpos($vo['source'],'wxapp')===0){</php>										{pigcms{$client.4}										<php>}elseif(strpos($vo['source'],'wap')===0){</php>										{pigcms{$client.0}										<php>}elseif($vo['client'] == 2 || strpos($vo['source'],'androidapp')===0){</php>										{pigcms{$client.2}										<php>}elseif($vo['client'] == 1 || strpos($vo['source'],'iosapp')===0){</php>										{pigcms{$client.1}										<php>}else{</php>										{pigcms{$client.3}										<php>}</php></td>										<td class="textcenter"><if condition="$vo['status'] eq 1"><font color="green">正常</font><elseif condition="$vo['status'] eq 2" /><font color="red">未审核</font><else /><font color="red">禁用</font></if></td>										<if condition="$config.open_user_spread eq 1 AND ($vo.openid neq '' OR $vo.wxapp_openid neq '')"><td class="textcenter"><a href="<php>if($vo['spread_count']>0){</php> {pigcms{:U('User/spread_higher_user',array('openid'=>$vo['openid'],'from_uid'=>$_GET['from_uid'],'lvl'=>$_GET['lvl'],'uid'=>$vo['uid']))}<php>}else{</php>javascript:void(0)<php>}</php>" >上级用户</a></td></if>										<if condition="$config.open_user_spread eq 1 AND ($vo.openid neq '' OR $vo.wxapp_openid neq '')"><td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo['spread_money']}</td></if>										<td class="textcenter"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/edit',array('uid'=>$vo['uid']))}','编辑用户信息',680,560,true,false,false,editbtn,'edit',true);"><if condition="$vo['status'] eq 2">审核<else />编辑</if></a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>